CREATE QUERY get_event_winner(STRING venue_name, DATETIME event_date) FOR GRAPH Olympicgraphrag2 {
  TYPETUPLE <string athlete_name, string medal_type, string event_title> ResultRow;
  ListAccum<ResultRow> @@results;

  S = {Venue.*};
  V = SELECT v FROM S v WHERE v.location_name LIKE "%Richmond Olympic Oval%";

  E = SELECT e FROM V-(HELD_AT)<-OlympicEvent e 
      WHERE e.date_held == to_datetime("2010-02-17");

  A = SELECT a FROM E-(WINS_MEDAL_IN)<-Athlete a
      ACCUM @@results += ResultRow(a.name, edge.medal_type, e.title);

  PRINT @@results;
}
INVOKE QUERY get_event_winner(_, _)

