CREATE QUERY find_walk_gold() FOR GRAPH Olympicgraphrag2 {
  TYPEDEF SET<STRING> STRING_SET;
  Or = SELECT g FROM OlympicGames:g WHERE g.year < 2016 ORDER BY g.year DESC LIMIT 1;
  Ev = SELECT e FROM Or:o -(PART_OF_GAMES:p)<- OlympicEvent:e WHERE e.gender == "Men" AND (e.title LIKE "%20km%" OR e.title LIKE "%20 kilometres%" OR e.title LIKE "%20 Kilometer%");

  PRINT Or, Ev;
}
INSTALL QUERY find_walk_gold
RUN QUERY find_walk_gold()

INTERPRET QUERY () FOR GRAPH Olympicgraphrag2 {
  Or = SELECT g FROM OlympicGames:g WHERE g.year < 2016 ORDER BY g.year DESC LIMIT 1;
  Ev = SELECT e FROM Or:o -(PART_OF_GAMES:p)<- OlympicEvent:e WHERE e.gender == "Men" AND (e.title LIKE "%20km%" OR e.title LIKE "%20 kilometres%" OR e.title LIKE "%20 Kilometer%");
  Athletes = SELECT a FROM Ev:e -(WINS_MEDAL_IN:w)- Athlete:a WHERE w.medal_type == "Gold";
  PRINT Or, Ev, Athletes;
}

INTERPRET QUERY () FOR GRAPH Olympicgraphrag2 {
  Summ = SELECT g FROM OlympicGames:g;
  PRINT Summ;
}

