USE GRAPH Olympicgraphrag2
TYPDEF struct ResultStruct (string event_id, string event_title, string games_year, string athlete_name, string medal_type)
// Let's find the Olympic Games held immediately before 2016 and the men's cross-country cycling event.
// Let's run a GSQL query to find OlympicGames, OlympicEvents, Sport, and Athlete who won a gold medal in cross-country cycling.
res = SELECT e
      FROM OlympicGames:g -(PART_OF_GAMES:p)<- OlympicEvent:e -(BELONGS_TO_SPORT:b)-> Sport:s,
           Athlete:a -(WINS_MEDAL_IN:w)-> e
      WHERE g.year < 2016 AND (s.discipline_name LIKE "%Cycling%" OR s.discipline_name LIKE "%cross-country%" OR e.title LIKE "%cross-country%" OR e.title LIKE "%Cycling%") AND e.gender == "Men" AND w.medal_type == "Gold"
      ORDER BY g.year DESC
      LIMIT 10;
PRINT res;

INTERPRET QUERY () FOR GRAPH Olympicgraphrag2 {
  TYPDEF tuple<string event_id, string event_title, int games_year, string athlete_name, string medal_type> ResType;
  SetAccum<ResType> @@results;

  // Find Olympic Games before 2016
  g_set = {OlympicGames.*};
  ev_set = SELECT e FROM g_set:g -(PART_OF_GAMES)<- OlympicEvent:e
           WHERE g.year < 2016 AND e.gender == "Men" AND (e.title LIKE "%cross-country%" OR e.title LIKE "%Cross-country%" OR e.title LIKE "%Cross-Country%");

  // Filter by sport or event title containing cycling / cross-country
  selected_ev = SELECT e FROM ev_set:e -(BELONGS_TO_SPORT)-> Sport:s
                WHERE s.discipline_name LIKE "%Cycling%" OR s.discipline_name LIKE "%mountain%" OR s.discipline_name LIKE "%Mountain%" OR s.discipline_name LIKE "%bike%";

  IF selected_ev.size() == 0 THEN
    selected_ev = ev_set;
  END;

  res = SELECT a FROM selected_ev:e -(WINS_MEDAL_IN:w)-> Athlete:a
        WHERE w.medal_type == "Gold";

  PRINT selected_ev, res;
}

INTERPRET QUERY () FOR GRAPH Olympicgraphrag2 {
  SumAccum<string> @event_title;
  SumAccum<string> @athlete_name;
  SumAccum<string> @medal;
  SumAccum<int> @games_year;

  // Let's get athletes who won gold medals in men's cross country cycling events

  OrAccum @@found;

  // Let's just print events and athletes directly using SELECT
  athletes = SELECT a 
             FROM Athlete:a -(WINS_MEDAL_IN:w)-> OlympicEvent:e -(PART_OF_GAMES)-> OlympicGames:g,
                  e -(BELONGS_TO_SPORT)-> Sport:s
             WHERE g.year < 2016 
               AND (e.title LIKE "%Cross-country%" OR e.title LIKE "%cross-country%" OR s.discipline_name LIKE "%Cycling%")
               AND e.gender == "Men"
               AND w.medal_type == "Gold";

  PRINT athletes;
}

